rss.channel:
REFRACT - Photography Improvement Log
Automated photography analysis and enhancement powered by multi-LLM critique.
{{ build_date }}
{% for entry in entries %}


  {{ entry.original_filename }} - Score {{ entry.consensus_score or entry.score }}/100
  {{ entry.entry_id }}.html
  {{ entry.entry_id }}
  {{ entry.timestamp }}

    {% if entry.genre and entry.genre != 'unknown' %}Genre: {{ entry.genre }}. {% endif %}
    Score: {{ entry.consensus_score or entry.score }}/100.
    {% if entry.re_review and entry.re_review.score_delta is defined %}
    After editing: {{ entry.re_review.consensus_score }}/100 ({{ '+' if entry.re_review.score_delta > 0 }}{{ entry.re_review.score_delta }}).
    {% endif %}
    {% if entry.improvements_display %}
    Improvements: {{ entry.improvements_display | join('; ') }}.
    {% endif %}


{% endfor %}
